(()=>{'use strict';renderPrototypeNav('person');const content=window.PROTOTYPE_CONTENT,groups=window.PROJECT_GROUPS;
const featured=[{p:groups[0].links[0],label:'Semiconductor',tag:'产业研究 · 制造机会',number:'18 Å',color:'#bbd8cc'},{p:groups[0].links[4],label:'Intel × Tesla',tag:'项目研究 · 产业观察',number:'R&D',color:'#bdcadb'},{p:groups[1].links[5],label:'Applied AI',tag:'AI 应用 · 企业转型',number:'AI',color:'#c9b8df'},{p:groups[2].links[0],label:'Beyond Work',tag:'个人项目 · 保持好奇',number:'IDEA',color:'#f2ca97'}];
document.querySelector('.work-list').innerHTML=featured.map((f,i)=>`<a href="${f.p.href}" target="_blank" rel="noopener" data-preview="${i}"><h3>${f.label}</h3><span>${f.tag}</span></a>`).join('');document.querySelector('.career-grid').innerHTML=content.career;document.querySelector('.education').innerHTML=content.education;document.querySelector('#project-directory').innerHTML=groups.map(g=>`<details open><summary>${g.zh}<span>${g.links.length} 个项目</span></summary><div class="directory-links">${g.links.map(p=>`<a href="${p.href}" target="_blank" rel="noopener"><span><b>${p.title.zh}</b><small>${p.description.zh}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div></details>`).join('');
const preview=document.querySelector('.hover-preview');document.querySelectorAll('[data-preview]').forEach(el=>{el.addEventListener('pointerenter',e=>{if(e.pointerType==='touch'||matchMedia('(max-width:760px)').matches)return;const f=featured[Number(el.dataset.preview)];preview.style.background=f.color;preview.querySelector('.hover-topic').textContent=f.p.title.zh;preview.querySelector('.hover-number').textContent=f.number;preview.classList.add('is-visible');});el.addEventListener('pointermove',e=>{preview.style.left=Math.max(155,Math.min(innerWidth-155,e.clientX))+'px';preview.style.top=e.clientY+'px';});el.addEventListener('pointerleave',()=>preview.classList.remove('is-visible'));});
document.querySelectorAll('.magnetic').forEach(el=>{el.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||document.body.dataset.motion==='off')return;const r=el.getBoundingClientRect();el.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.18}px,${(e.clientY-r.top-r.height/2)*.18}px)`;});el.addEventListener('pointerleave',()=>el.style.transform='');});
const floating=document.querySelector('.floating-menu');function scrollUpdate(){floating.classList.toggle('shown',scrollY>innerHeight*.65);}window.addEventListener('scroll',scrollUpdate,{passive:true});scrollUpdate();
if('IntersectionObserver' in window){document.body.classList.add('js-reveals');const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-in');obs.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));}
})();
